const body = $input.first().json.body || $input.first().json;
// n8n puts the POST body under .body; fall back to the item itself when testing.

const slots = Array.isArray(body.slots) ? body.slots : [];
const outline = body.outline || {};
if (slots.length === 0) throw new Error('slots must contain at least one slot');
if (!Array.isArray(outline.paragraphs)) throw new Error('outline.paragraphs is required');

const prompt = [
  'SLOTS TO FIND (return exactly one answer per slot key):', JSON.stringify(slots, null, 1),
  '', 'DOCUMENT OUTLINE:',
  'Paragraphs (ref, text, red = runs written in red, cell = table cell it is in):', JSON.stringify(outline.paragraphs),
  '', 'Tables:', JSON.stringify(outline.tables || []),
  '', 'Images:', JSON.stringify(outline.images || []),
  '', 'Word fields (SET holds a stored sample value and is never a location; a REF field shows a value and can be replaced as a whole, runs = its first and last run):', JSON.stringify(outline.fields || []),
  '', 'SAMPLE VALUES THAT APPEAR IN MORE THAN ONE PLACE (text, places). If a value belongs to a slot, list every place:', JSON.stringify(outline.redValues || [])
].join('\n');

return [{ json: { prompt: prompt, slots: slots } }];

const slots = $('Build Prompt').first().json.slots || [];
// The slot list the backend sent; only these keys are ever returned.

let raw = String($input.first().json.output || '').trim();
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed = null;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try { parsed = JSON.parse(raw.substring(start, end + 1)); } catch (e2) { parsed = null; }
  }
}

if (!parsed || typeof parsed !== 'object' || !Array.isArray(parsed.mappings)) {
  return [{ json: { error: 'invalid_ai_output', raw: raw.substring(0, 2000) } }];
}

const wanted = {};
slots.forEach(function (s) { wanted[s.key] = true; });
const seen = {};
const mappings = [];
parsed.mappings.forEach(function (m) {
  if (!m || typeof m !== 'object' || !wanted[m.key] || seen[m.key]) return;
  seen[m.key] = true;
  mappings.push(m);
});

return [{ json: { mappings: mappings } }];
